export function AssignmentNotification({
  assigner = '{{assigner}}',
  task = '{{task}}',
  assignee = '{{assignee}}',
  priority = '{{priority}}',
  timestamp = '{{timestamp}}',
  read = {{read}},
}) {
  const border = { low: '#A8E6C1', medium: '#BFD9F2', high: '#E8A020' }[priority] ?? '#BFD9F2';
  const icon = { low: '\u2193', medium: '\u2192', high: '\u2191' }[priority] ?? '\u2192';
  const srOnly = { position: 'absolute', width: 1, height: 1, padding: 0, margin: -1, overflow: 'hidden', clip: 'rect(0,0,0,0)', whiteSpace: 'nowrap', border: 0 };
  return (
    <article style={{ display: 'flex', alignItems: 'flex-start', gap: 12, maxWidth: 420, padding: '14px 16px', background: '#FAF7F2', color: '#241430', borderRadius: 10, boxShadow: '0 6px 18px rgba(36,20,48,.12)', fontFamily: 'system-ui, sans-serif', fontSize: 14, position: 'relative', borderLeft: `4px solid ${border}` }}>
      <span aria-hidden='true' style={{ width: 22, height: 22, borderRadius: 6, flexShrink: 0, background: '#24143014', display: 'grid', placeItems: 'center', fontWeight: 700, fontSize: 11 }}>{icon}</span>
      <div style={{ flex: 1 }}>
        <p style={{ margin: '0 0 4px' }}><strong>{assigner}</strong> assigned <strong>{task}</strong> to {assignee}</p>
        <p style={{ margin: '0 0 4px', fontSize: 12, color: '#241430b3' }}>Priority: <span style={{ textTransform: 'capitalize', fontWeight: 600 }}>{priority}</span></p>
        <time style={{ display: 'block', fontSize: 11, color: '#24143080' }} dateTime={timestamp}>{timestamp}</time>
      </div>
      {!read && (
        <>
          <span aria-hidden='true' style={{ position: 'absolute', top: 14, right: 14, width: 8, height: 8, borderRadius: '50%', background: '#b0273e' }} />
          <span style={srOnly}>Unread</span>
        </>
      )}
    </article>
  );
}
